import { DeviceIdentityTemplate } from './models';
import { GPU_DATABASE } from './gpu';

export class DatasetValidator {
    /**
     * Prevents impossible combinations generated by the random Entropy selector.
     * Ensures we don't accidentally spit out an Apple GPU on Android.
     */
    public static validateTemplateCombination(template: DeviceIdentityTemplate): boolean {
        // Rule 1: Safari is exclusive to Apple hardware
        if (template.browserFamily === 'Safari') {
            if (!template.os.includes('macOS') && !template.os.includes('iOS')) {
                console.error(`[DatasetValidator] Invalid combination: Safari selected on ${template.os}`);
                return false;
            }
        }

        // Rule 2: macOS and iOS must ONLY use Apple Inc. vendor configurations
        if (template.os.includes('macOS') || template.os.includes('iOS')) {
            const validApple = GPU_DATABASE.some(g => g.compatibleOS.includes(template.os) && g.vendorId.includes('apple'));
            if (!validApple) {
                console.error(`[DatasetValidator] Invalid combination: Non-Apple GPU matched with Apple OS.`);
                return false;
            }
        }

        return true;
    }
}
